<?php
namespace App\Http\Controllers;
use App\Models\{Product,Sale,Purchase,ReturnItem,StockMovement};use App\Services\InventoryService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class ReturnController extends Controller{
 public function index(){return view('returns.index',['returns'=>DB::table('returns')->leftJoin('contacts','contacts.id','=','returns.contact_id')->select('returns.*','contacts.name as contact_name')->latest('returned_at')->paginate(30),'sales'=>Sale::latest('sold_at')->limit(100)->get(),'purchases'=>Purchase::latest('purchased_at')->limit(100)->get(),'products'=>Product::with('baseUnit')->where('is_active',1)->orderBy('name')->get()]);}
 public function store(Request $r,InventoryService $inventory){$d=$r->validate(['return_type'=>'required|in:sale,purchase','original_id'=>'nullable|integer','product_id'=>'required|exists:products,id','quantity'=>'required|numeric|gt:0','unit_price'=>'required|numeric|min:0','reason'=>'required|string|max:190']);DB::transaction(function()use($d,$inventory){$p=Product::with('baseUnit')->findOrFail($d['product_id']);$orig=$d['return_type']==='sale'?Sale::find($d['original_id']??0):Purchase::find($d['original_id']??0);if($d['original_id']&&!$orig)throw ValidationException::withMessages(['original_id'=>'Original invoice not found.']);$no='RET-'.now()->format('ymd').'-'.Str::upper(Str::random(5));$rid=DB::table('returns')->insertGetId(['return_type'=>$d['return_type'],'return_no'=>$no,'original_id'=>$orig?->id,'contact_id'=>$orig?($d['return_type']==='sale'?$orig->customer_id:$orig->supplier_id):null,'total'=>$d['quantity']*$d['unit_price'],'returned_at'=>now(),'reason'=>$d['reason'],'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);ReturnItem::create(['return_id'=>$rid,'product_id'=>$p->id,'quantity'=>$d['quantity'],'unit_price'=>$d['unit_price'],'line_total'=>$d['quantity']*$d['unit_price']]);$this->moveReturn($p,$d['return_type'],$d['quantity'],$inventory,$no);});return back()->with('success','Return recorded and stock updated.');}
 private function moveReturn(Product $p,string $type,float $qty,InventoryService $inventory,string $no):void{if($type==='sale')$inventory->move($p,null,$qty,'in','sale_return',null,(float)$p->purchase_price,'Return '.$no);else $inventory->move($p,null,$qty,'out','purchase_return',null,(float)$p->purchase_price,'Return '.$no);}
}
